sp_AlterarVencimentoContaPagar	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AlterarVencimentoContaPagar`(\n\n    IN p_idContaPagar INT,\n\n    IN p_novaData     DATE\n\n)\nBEGIN\n\n    UPDATE ContaPagar SET dthVencimento = p_novaData WHERE idContaPagar = p_idContaPagar;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
